import json,hashlib
p='/workspace/scratch/volume4/batch469-478.json';d=json.load(open(p))
def page(n,rows):
 ps=[]
 for i,(ar,ru) in enumerate(rows,1):
  sid=f'v4-p{n}-{i:02}';ps.append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=True))
  d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
 d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=ps))
page(472,[
('فشهادة الرب تعالى تكذب هؤلاء أشد التكذيب، وتضمن: أن الذي شهد به بينه وأوضحه وأظهره حتى جعله في أعلى مراتب الظهور والبيان، وأنه لو كان الحق ما تقوله المعطلة والجهمية لم يكن العباد قد انتفعوا بما شهد به سبحانه، فإن الحق الذي في نفس الأمر عندهم لم يشهد به لنفسه، والذي شهد به لنفسه وأظهره وأوضحه فليس بحق، ولا يجوز أن يستفاد منه الحق واليقين!', 'Свидетельство Всевышнего Господа самым решительным образом обличает их ложь. Оно включает то, что засвидетельствованное Им Он разъяснил, прояснил и обнаружил, доведя до высочайшей степени явности и ясности. Если бы истина заключалась в словах отрицающих качества и джахмитов, рабы не получили бы пользы от того, о чём засвидетельствовал Пречистый: ведь, по их мнению, о действительной истине Он о Себе не засвидетельствовал, а то, о чём Он засвидетельствовал, что обнаружил и прояснил, не является истиной и из этого нельзя извлекать истину и убеждённость!'),
('وأما آياته العيانية الخلقية، فالنظر فيها والاستدلال بها يدل على ما تدل عليه آياته القولية السمعية. وآيات الرب: هي دلالاته وبراهينه التي بها يعرفه العباد ويعرفون أسماءه وصفاته وتوحيده وأمره ونهيه. فالرسل تخبر عنه بكلامه الذي تكلم به وهو آياته القولية، ويستدلون على ذلك بمفعولاته التي تشهد على صحة ذلك وهي آياته العيانية، والعقل يجمع بين هذه وهذه، فيجزم بصحة ما جاءت به الرسل، فتتفق شهادة السمع والبصر والعقل والفطرة. وهو سبحانه ـ لكمال عدله ورحمته، وإحسانه وحكمته، ومحبته للعذر، وإقامته للحجة ـ لم يبعث نبيا من الأنبياء إلا ومعه آية تدل على صدقه فيما أخبر به.', 'Что касается Его зримых знамений творения, их рассмотрение и заключение по ним указывают на то же, на что указывают Его словесные, слышимые знамения. Знамения Господа — это Его указания и доводы, благодаря которым рабы познают Его, Его имена, качества и единственность, Его повеление и запрет. Посланники сообщают о Нём посредством Его речи, которую Он произнёс, — это Его словесные знамения; они приводят в доказательство Его творения, свидетельствующие о верности этого, — это Его зримые знамения. Разум соединяет одни с другими и твёрдо удостоверяется в истинности принесённого посланниками. Так сходятся свидетельства слуха, зрения, разума и естества. Пречистый по совершенству Своей справедливости, милости, благодеяния и мудрости, любви к оправданию и установлению довода не посылал ни одного пророка без знамения, указывающего на его правдивость в том, о чём он сообщил.'),
('قال تعالى: {لقد أرسلنا رسلنا بالبينات وأنزلنا معهم الكتاب', 'Всевышний сказал: {لقد أرسلنا رسلنا بالبينات وأنزلنا معهم الكتاب')])
page(473,[
('والميزان ليقوم الناس بالقسط} [الحديد: ٢٥]. وقال تعالى: {وما أرسلنا من قبلك إلا رجالا يوحى إليهم فاسألوا أهل الذكر إن كنتم لا تعلمون بالبينات والزبر} [النحل: ٤٣]. وقال تعالى: {قد جاءكم رسل من قبلي بالبينات وبالذي قلتم فلم قتلتموهم إن كنتم صادقين فإن كذبوك فقد كذب رسل من قبلك جاءوا بالبينات والزبر والكتاب المنير} [آل عمران: ١٨٣ ـ ١٨٤]. وقال تعالى: {وإن يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينات وبالزبر وبالكتاب المنير} [فاطر: ٢٥].', 'والميزان ليقوم الناس بالقسط} — «Мы отправили Наших посланников с ясными доказательствами и ниспослали с ними Писание и Весы, чтобы люди придерживались справедливости» [57:25]. Всевышний сказал: {وما أرسلنا من قبلك إلا رجالا يوحى إليهم فاسألوا أهل الذكر إن كنتم لا تعلمون بالبينات والزبر} — «До тебя Мы посылали только мужей, которым внушалось откровение. Спросите людей Напоминания, если вы не знаете. С ясными доказательствами и Писаниями» [16:43–44]. Всевышний сказал: {قد جاءكم رسل من قبلي بالبينات وبالذي قلتم فلم قتلتموهم إن كنتم صادقين فإن كذبوك فقد كذب رسل من قبلك جاءوا بالبينات والزبر والكتاب المنير} — «До меня к вам уже приходили посланники с ясными доказательствами и тем, о чём вы говорите. Почему же вы убивали их, если вы правдивы? Если они считают тебя лжецом, то и до тебя считали лжецами посланников, приходивших с ясными доказательствами, Писаниями и озаряющей Книгой» [3:183–184]. Всевышний сказал: {وإن يكذبوك فقد كذب الذين من قبلهم جاءتهم رسلهم بالبينات وبالزبر وبالكتاب المنير} — «Если они считают тебя лжецом, то и жившие до них считали лжецами: к ним приходили их посланники с ясными доказательствами, Писаниями и озаряющей Книгой» [35:25].'),
('حتى إن من أخفى آيات الرسل آيات هود عليه السلام، حتى قال له قومه: {يا هود ما جئتنا ببينة} [هود: ٥٣]، ومع هذا فبينته من أظهر البينات. وقد أشار إليها بقوله: {قال إني أشهد الله واشهدوا أني بريء مما تشركون من دونه فكيدوني جميعا ثم لا تنظرون إني توكلت على الله ربي وربكم ما من دابة إلا هو آخذ بناصيتها إن ربي على صراط مستقيم} [هود: ٥٤ ـ ٥٦]. فهذا من أعظم الآيات: أن رجلا واحدا يخاطب أمة عظيمة بهذا الخطاب غير جزع ولا فزع ولا خوار، بل هو واثق بما قاله جازم به، فأشهد الله أولا على براءته من دينهم وما هم عليه إشهاد واثق به، معتمد عليه، معلم لقومه أنه وليه وناصره وغير مسلط لهم عليه.', 'Среди самых скрытых знамений посланников — знамения Худа, мир ему. Его народ даже сказал: {يا هود ما جئتنا ببينة} — «О Худ, ты не принёс нам ясного доказательства» [11:53]. При этом его доказательство — одно из самых явных. Он указал на него словами: {قال إني أشهد الله واشهدوا أني بريء مما تشركون من دونه فكيدوني جميعا ثم لا تنظرون إني توكلت على الله ربي وربكم ما من دابة إلا هو آخذ بناصيتها إن ربي على صراط مستقيم} — «Он сказал: “Я призываю Аллаха в свидетели, и вы засвидетельствуйте, что я непричастен к тем, кого вы приобщаете к Нему помимо Него. Замышляйте же против меня все вместе и не давайте мне отсрочки. Я уповаю на Аллаха, моего Господа и вашего Господа. Нет ни одного живого существа, которого Он не держал бы за чёлку. Поистине, мой Господь — на прямом пути”» [11:54–56]. Это одно из величайших знамений: один человек обращается так к огромному народу без тревоги, страха и слабости, уверенный в своих словах и твёрдо убеждённый в них. Сначала он призвал Аллаха в свидетели своей непричастности к их религии и их воззрениям — призвал, будучи уверенным в Нём и полагаясь на Него, давая своему народу знать, что Он — его Покровитель и Помощник и не даст им власти над ним.')])
page(474,[
('ثم أشهدهم ـ إشهاد مجاهر لهم بالمخالفة: أنه بريء من دينهم وآلهتهم التي يوالون عليها، ويعادون عليها، ويبذلون دماءهم وأموالهم في نصرتها.', 'Затем он призвал в свидетели их самих, открыто объявляя им своё несогласие: он непричастен к их религии и их божествам, ради которых они дружат и враждуют, проливают свою кровь и расходуют имущество, защищая их.'),
('ثم أكد عليهم ذلك بالاستهانة بهم واحتقارهم وازدرائهم، وكونهم يجتمعون كلهم على كيده وشفاء غيظهم منه، ثم يعاجلونه ولا يمهلونه. وفي ضمن ذلك: أنكم أضعف وأعجز وأقل من ذلك، وأنكم لو رمتموه لانقلبتم بغيظكم مكبوتين مخذولين.', 'Затем он подтвердил это, выказав им пренебрежение, презрение и уничижение: пусть они все соберутся, чтобы замыслить против него и утолить свой гнев на него, а затем немедленно нападут, не давая отсрочки. В этом заключено: вы слишком слабы, бессильны и ничтожны для такого; если вы попытаетесь это сделать, то вернётесь со своим гневом посрамлёнными и лишёнными поддержки.'),
('ثم قرر دعوته أحسن تقرير، وبين أن ربه تعالى ربهم الذي نواصيهم بيده هو وليه ووكيله القائم بنصره وتأييده، وأنه على صراط مستقيم، فلا يخذل من توكل عليه وآمن به، ولا يشمت به أعداءه، ولا يكون معهم عليه، فإن صراطه المستقيم الذي هو عليه في قوله وفعله يمنع ذلك ويأباه.', 'Затем он самым прекрасным образом утвердил свой призыв и разъяснил, что его Всевышний Господь — их Господь, держащий их за чёлки, — его Покровитель и Тот, Кому он вверяет себя, поддерживающий и помогающий ему. Он — на прямом пути и потому не оставит без помощи того, кто уповает на Него и верит в Него, не даст врагам злорадствовать над ним и не станет на их сторону против него. Его прямой путь в словах и делах исключает и отвергает такое.'),
('وتحت هذا الخطاب: أن من صراطه المستقيم أن ينتقم ممن خرج عنه وعمل بخلافه، وينزل به بأسه؛ فإن الصراط المستقيم هو العدل الذي الرب تعالى عليه، ومنه انتقامه من أهل الشرك والإجرام ونصرة أوليائه ورسله عليهم، وأنه يذهبهم ويستخلف قوما غيرهم ولا يضره ذلك شيئا، وأنه القائم سبحانه على كل شيء حفظا ورعاية وتدبيرا وإحصاء.', 'В этих словах также заключено, что к Его прямому пути относится возмездие тому, кто с него сошёл и поступал вопреки ему, и ниспослание ему Своей кары. Прямой путь — это справедливость Всевышнего Господа; к ней относятся Его возмездие приверженцам многобожия и преступления, помощь Своим приближённым и посланникам против них, уничтожение их и замена другим народом, что ничем Ему не повредит. Пречистый надзирает за всем, сохраняя, оберегая, управляя и учитывая.')])
json.dump(d,open(p,'w'),ensure_ascii=False,indent=2)
